def _shapes(k):
    res = []
    def go(pref, used, st):
        if used == k and st == 1:
            res.append(pref)
            return
        if used < k:
            go(pref + 'n', used + 1, st + 1)
        if st > 1:
            go(pref + 'o', used, st - 1)
    go('', 0, 0)
    return res


def _all(digs):
    out = {}
    for per in set(itertools.permutations(digs)):
        for sh in _shapes(4):
            for ops in itertools.product('+-*', repeat=3):
                st = []
                di = oi = 0
                txt = ''
                for ch in sh:
                    if ch == 'n':
                        st.append(per[di])
                        txt += str(per[di])
                        di += 1
                    else:
                        b = st.pop()
                        a = st.pop()
                        o = ops[oi]
                        oi += 1
                        txt += o
                        st.append(a + b if o == '+' else a - b if o == '-' else a * b)
                out.setdefault(st[0], []).append(txt)
    return out


def generate(seed):
    r = random.Random(seed)
    for _ in range(40):
        digs = [r.randint(1, 9) for _ in range(4)]
        out = _all(digs)
        cand = [(len(v), k) for k, v in out.items() if 10 <= k <= 99]
        if not cand:
            continue
        cand.sort()
        lo = cand[0][0]
        pick = [k for n, k in cand if n <= lo + 2]
        return ''.join(str(d) for d in digs) + '=' + str(r.choice(pick))
    return '1234=10'

